<template>
  <section v-if="summary?.campaign || (summary?.wallet?.available_cents ?? 0) > 0 || summary?.history.length || error" id="consumption-rewards" ref="rewardsRef" tabindex="-1" class="card reward-strip" :aria-labelledby="campaign ? titleID : undefined" :aria-label="campaign ? undefined : t('dashboard.consumption.balanceAndHistory')">
    <template v-if="campaign">
      <label v-if="(summary?.campaigns?.length ?? 0)>1" :for="campaignSelectID" class="reward-campaign-picker">{{ t('dashboard.consumption.chooseCampaign') }} <select :id="campaignSelectID" name="reward_campaign" :value="campaign.id" @change="selectCampaign"><option v-for="item in summary?.campaigns" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
      <header class="reward-strip-head"><div class="reward-strip-heading"><h2 :id="titleID">{{ copy.title }}</h2><span class="reward-strip-spent">{{ t('dashboard.consumption.spent',{amount:displaySpend}) }}</span></div><div class="reward-strip-actions"><p>{{ nextTier?t('dashboard.consumption.next',{amount:remaining,reward:money(nextTier.reward_cents)}):t('dashboard.consumption.allReached') }}</p><button type="button" class="reward-rules-toggle" :aria-expanded="rulesOpen" :aria-controls="rulesID" @click="rulesOpen=!rulesOpen">{{ copy.rules }}</button></div></header>
      <progress class="sr-only" :value="Number(summary?.spend || 0)" :max="(campaign.tiers.at(-1)?.threshold_cents || 1)/100" :aria-label="t('dashboard.consumption.progress')" />
      <div v-if="firstTierProgress !== null" class="reward-first-progress"><span>{{ t('dashboard.consumption.firstTierProgress',{percent:firstTierProgress}) }}</span><progress :value="firstTierProgress" max="100" :aria-label="t('dashboard.consumption.progress')" /></div>
      <div class="reward-path-scroll"><div class="reward-path" :style="{'--tier-count':campaign.tiers.length}"><div class="reward-path-line" aria-hidden="true"><span :style="{width:pathProgress+'%'}"></span><i v-if="pathProgress>0&&pathProgress<100" :style="{left:pathProgress+'%'}"></i></div><ol class="reward-milestones"><li v-for="tier in campaign.tiers" :key="tier.position" class="reward-milestone" :class="{'is-reached':reached(tier.threshold_cents),'is-claimed':tier.state==='claimed','is-claimable':tier.state==='reserved'&&canClaim}"><span class="reward-node" aria-hidden="true"><Icon :name="tier.state==='claimed'||reached(tier.threshold_cents)?'check':'lock'" size="sm" /></span><span class="reward-tier-label"><b>{{ money(tier.threshold_cents) }}</b><span>{{ copy.gift }}</span><strong>{{ money(tier.reward_cents) }}</strong></span><button v-if="tier.state==='reserved'&&canClaim" type="button" class="reward-claim" :disabled="claiming" @click="claim(tier.position)">{{ t('dashboard.consumption.claim',{amount:money(tier.reward_cents)}) }}</button><span v-else-if="tier.state&&tier.state!=='locked'" class="reward-tier-state">{{ t(`dashboard.consumption.states.${tier.state}`) }}</span><span v-else-if="reached(tier.threshold_cents)" class="reward-tier-state">{{ copy.reached }}</span><span class="sr-only">{{ t('dashboard.consumption.stage',{n:tier.position}) }}: {{ t(`dashboard.consumption.states.${tier.state||'locked'}`) }}</span></li></ol></div></div>
      <div v-if="summary?.enabled===false || summary?.processing_pending || summary?.awards_enabled===false || summary?.blocked || summary?.budget_blocked || summary?.block_reason || phase!=='active'" class="reward-strip-notice" role="status"><span v-if="summary?.awards_enabled===false">{{ copy.paused }}</span><span v-else-if="summary?.blocked">{{ t('dashboard.consumption.review') }}</span><span v-else-if="summary?.enabled===false">{{ copy.masterPaused }}</span><span v-else-if="phase!=='active'">{{ t(`dashboard.consumption.phases.${phase}`) }}</span><span v-else-if="summary?.block_reason==='user_cap'">{{ t('dashboard.consumption.userCapReached') }}</span><span v-else-if="summary?.budget_blocked">{{ t('dashboard.consumption.noBudget') }}</span><span v-else>{{ copy.pending }}</span></div>
      <div v-if="summary?.claimable_cents && canClaim" class="reward-claim-all"><span>{{ t('dashboard.consumption.claimable',{amount:money(summary.claimable_cents)}) }}</span><button type="button" class="reward-claim" :disabled="claiming" @click="claim(0)">{{ t('dashboard.consumption.claimAll') }}</button></div>
      <p v-if="summary?.claimable_cents && canClaim" class="reward-wallet-help">{{ t('dashboard.consumption.deadline',{date:date(campaign.claim_until)}) }}<br>{{ t('dashboard.activity.walletNext') }}</p>
      <div v-if="rulesOpen" :id="rulesID" class="reward-rules"><h3>{{ campaign.name }}</h3><p>{{ date(campaign.starts_at) }} — {{ date(campaign.ends_at) }} · {{ t('dashboard.consumption.beijing') }}</p><p>{{ t('dashboard.consumption.rule') }}</p><p>{{ t('dashboard.consumption.deadline',{date:date(campaign.claim_until)}) }}</p></div>
    </template>
    <div v-if="(summary?.wallet?.available_cents ?? 0) > 0" class="reward-wallet-bar">
      <span>{{ t('dashboard.activity.walletAvailable') }}: <strong>{{ money(summary!.wallet.available_cents) }}</strong></span>
      <button type="button" data-testid="consumption-withdraw" class="reward-claim" :disabled="withdrawing || summary?.wallet?.withdraw_blocked" :aria-busy="withdrawing" @click="withdraw">{{ withdrawing ? t('dashboard.activity.transferring') : t('dashboard.activity.transferAll',{amount:((summary?.wallet?.available_cents??0)/100).toFixed(2)}) }}</button>
    </div>
    <p v-if="(summary?.wallet?.available_cents??0)>0" class="reward-wallet-help">{{ t('dashboard.activity.walletShared') }} {{ t('dashboard.activity.walletUse') }}</p>
    <p v-if="summary?.wallet?.withdraw_blocked && ((summary.wallet.available_cents??0)>0 || (summary.wallet.recovery_debt_cents??0)>0)" class="reward-strip-notice" role="status">{{ t(walletTransferBlockKey(summary.wallet.withdraw_block_reason)) }}</p>
    <p v-if="notice" class="reward-notice" role="status">{{ notice }}</p>
    <details v-if="summary" class="reward-history text-gray-600 dark:text-dark-300"><summary class="cursor-pointer">{{ t('dashboard.consumption.balanceAndHistory') }}</summary><p class="mt-3 text-xs">{{ t('dashboard.consumption.walletStats', {available:Number(summary?.wallet?.available||0).toFixed(2),earned:Number(summary?.wallet?.total_earned||0).toFixed(2),withdrawn:Number(summary?.wallet?.total_withdrawn||0).toFixed(2)}) }}</p><p class="mt-2 text-xs text-gray-500">{{ t('dashboard.consumption.walletHint') }}</p><ul v-if="summary?.wallet?.ledger?.length" class="mt-3 space-y-1.5"><li v-for="entry in summary.wallet.ledger" :key="`w-${entry.id}`" class="flex flex-wrap justify-between gap-2 border-b border-gray-100 py-1.5 text-xs dark:border-dark-700"><span>{{ t(`dashboard.activity.ledgerKinds.${entry.kind}`) }} · {{ date(entry.created_at) }}</span><strong :class="entry.direction!=='credit'?'text-sky-600 dark:text-sky-400':'text-emerald-600 dark:text-emerald-400'">{{ entry.direction==='credit'?'+':'-' }}{{ money(entry.amount_cents) }}</strong></li></ul><ul class="mt-3 space-y-2"><li v-for="(item,index) in summary?.history" :key="index" class="flex flex-wrap justify-between gap-2 border-b border-gray-100 py-2 dark:border-dark-700"><span>{{ item.campaign }} · {{ t('dashboard.consumption.stage', {n:item.position}) }}</span><span>{{ money(item.reward_cents) }} · {{ t(`dashboard.consumption.states.${item.state}`) }}</span></li></ul></details>
    <p v-if="error" class="reward-error" role="alert">{{ error }} <button type="button" @click="refresh">{{ copy.retry }}</button></p>
  </section>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,useId} from 'vue'
import {consumptionUnits, thresholdUnits, consumptionDisplay, consumptionGap} from '@/utils/consumptionAmount'
import {useI18n} from 'vue-i18n'
import Icon from '@/components/icons/Icon.vue'
import {consumptionAPI,type ConsumptionSummary} from '@/api/consumption'
import {extractApiErrorMessage} from '@/utils/apiError'
import {useAuthStore} from '@/stores/auth'
import {walletTransferBlockKey} from '@/utils/activityWallet'
const {t,locale}=useI18n();const auth=useAuthStore();const summary=ref<ConsumptionSummary|null>(null);const error=ref('');const notice=ref('');const claiming=ref(false);const withdrawing=ref(false)
const rulesOpen=ref(false);const rulesID=useId();const titleID=useId();const campaignSelectID=useId();const selectedCampaign=ref<number>()
const rewardsRef=ref<HTMLElement|null>(null)
let focusRequested=window.location.hash==='#consumption-rewards'
async function focusRewards(){await nextTick();if(!rewardsRef.value)return;focusRequested=false;rewardsRef.value.scrollIntoView({block:'center',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});rewardsRef.value.focus({preventScroll:true})}
function requestClaim(event:Event){selectedCampaign.value=(event as CustomEvent<{campaignId?:number}>).detail?.campaignId;focusRequested=true;void refresh()}
function walletUpdated(){if(!claiming.value&&!withdrawing.value)void refresh()}
const copy=computed(()=>locale.value.startsWith('zh')?{title:'消费达标赠额度',rules:'活动规则',gift:'赠',refresh:'刷新进度',pending:'消费已记录，奖励资格正在结算',paused:'奖励发放暂时暂停',masterPaused:'消费奖励活动已关闭，关闭期间的消费不累计；已预留奖励仍可在截止前领取。',reached:'已达标，等待奖励确认',load:'奖励进度暂时加载失败',retry:'重试'}:{title:'Usage rewards',rules:'Activity rules',gift:'Get',refresh:'Refresh progress',pending:'Spending recorded; rewards are processing',paused:'Reward payouts are temporarily paused',masterPaused:'Usage rewards are off. Spending while off does not count; reserved rewards remain claimable until the deadline.',reached:'Threshold reached; awaiting confirmation',load:'Unable to load reward progress',retry:'Retry'})
const campaign=computed(()=>summary.value?.campaign)
const money=(cents:number)=>`$${(cents/100).toFixed(2)}`
const date=(value:string)=>new Intl.DateTimeFormat(locale.value,{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value))
const spendUnits=computed(()=>consumptionUnits(summary.value?.spend||'0'))
const displaySpend=computed(()=>consumptionDisplay(summary.value?.spend||'0'))
const nextTier=computed(()=>campaign.value?.tiers.find(tier=>thresholdUnits(tier.threshold_cents)>spendUnits.value))
const pathProgress=computed(()=>{
 const tiers=campaign.value?.tiers||[];if(!tiers.length)return 0
 const spend=spendUnits.value;const first=thresholdUnits(tiers[0]!.threshold_cents)
 if(spend<first)return 0
 if(tiers.length===1)return 100
 for(let i=1;i<tiers.length;i++){const end=thresholdUnits(tiers[i]!.threshold_cents),start=thresholdUnits(tiers[i-1]!.threshold_cents);if(spend<end){const fraction=Number((spend-start)*10000n/(end-start))/10000;return (i-1+fraction)/(tiers.length-1)*100}}
 return 100
})
const firstTierProgress=computed(()=>{
 const first=campaign.value?.tiers[0];if(!first)return null
 const threshold=thresholdUnits(first.threshold_cents);if(threshold<=0n||spendUnits.value>=threshold)return null
 return Math.max(0,Number(spendUnits.value*100n/threshold))
})
async function selectCampaign(event:Event){selectedCampaign.value=Number((event.target as HTMLSelectElement).value);await refresh()}
const reached=(threshold:number)=>spendUnits.value>=thresholdUnits(threshold)
const canClaim=computed(()=>summary.value?.awards_enabled!==false&&!summary.value?.blocked&&!expired.value)
const remaining=computed(()=>money(consumptionGap(summary.value?.spend||'0',nextTier.value?.threshold_cents||0)))
const now=ref(Date.now())
let timer:ReturnType<typeof setInterval>|undefined;let disposed=false;let refreshing=false;let refreshQueued=false;let summaryVersion=0
function onVisible(){if(document.visibilityState==='visible')void refresh()}
onUnmounted(()=>{disposed=true;clearInterval(timer);window.removeEventListener('focus',onVisible);document.removeEventListener('visibilitychange',onVisible);window.removeEventListener('activity-claim-requested',requestClaim);window.removeEventListener('activity-wallet-updated',walletUpdated)})
const expired=computed(()=>!!campaign.value&&now.value>=Date.parse(campaign.value.claim_until))
const phase=computed(()=>{const c=campaign.value;if(!c)return 'ended';if(expired.value)return 'expired';if(now.value>=Date.parse(c.ends_at))return 'ended';if(c.state!=='active')return 'paused';if(now.value<Date.parse(c.starts_at))return 'upcoming';return 'active'})
async function claim(position:number){if(!campaign.value||claiming.value)return;claiming.value=true;++summaryVersion;error.value='';notice.value='';try{const value=await consumptionAPI.claim(campaign.value.id,position);++summaryVersion;summary.value=value;notice.value=t('dashboard.activity.walletClaimed');window.dispatchEvent(new CustomEvent('activity-wallet-updated'))}catch(e){error.value=extractApiErrorMessage(e,t('dashboard.activity.actionFailed'))}finally{claiming.value=false}}
async function withdraw(){if(withdrawing.value||!summary.value||summary.value.wallet.withdraw_blocked||summary.value.wallet.available_cents<=0)return;withdrawing.value=true;++summaryVersion;error.value='';notice.value='';try{const w=await consumptionAPI.withdraw();++summaryVersion;summary.value.wallet=w;notice.value=t('dashboard.activity.withdrawSuccess',{amount:(w.withdrawn??0).toFixed(2)});window.dispatchEvent(new CustomEvent('activity-wallet-updated'));await Promise.allSettled([refresh(),auth.refreshUser()])}catch(e){error.value=extractApiErrorMessage(e,t('dashboard.activity.actionFailed'))}finally{withdrawing.value=false}}
async function refresh(){
 if(refreshing){refreshQueued=true;return}
 refreshing=true
 const requestedCampaign=selectedCampaign.value
 const version=summaryVersion
 try{const value=await consumptionAPI.status(requestedCampaign);if(!disposed&&version===summaryVersion&&requestedCampaign===selectedCampaign.value){summary.value=value;error.value=''}}
 catch(e){if(!disposed&&version===summaryVersion&&requestedCampaign===selectedCampaign.value)error.value=extractApiErrorMessage(e,t('dashboard.activity.loadFailed'))}
 finally{refreshing=false;if(!disposed&&focusRequested)void focusRewards();if(refreshQueued&&!disposed){refreshQueued=false;void refresh()}}
}
onMounted(()=>{void refresh();window.addEventListener('focus',onVisible);document.addEventListener('visibilitychange',onVisible);window.addEventListener('activity-claim-requested',requestClaim);window.addEventListener('activity-wallet-updated',walletUpdated);timer=setInterval(()=>{now.value=Date.now();if(document.visibilityState==='visible')void refresh()},30000)})

</script>

<style scoped>
.reward-strip{scroll-margin-top:160px}.reward-wallet-help{margin-top:8px;font-size:12px;line-height:1.8;color:#637083}.reward-wallet-bar{flex-wrap:wrap}.reward-strip:focus-visible{outline:2px solid #138467;outline-offset:4px}
.reward-first-progress{display:flex;gap:12px;align-items:center;font-size:12px;margin:10px 0;color:#637083}.reward-first-progress progress{width:120px;height:6px;accent-color:#159a74}.reward-campaign-picker{display:flex;gap:10px;align-items:center;font-size:12px;margin-bottom:12px}.reward-campaign-picker select{max-width:100%;padding:6px;border:1px solid #94a3b8;border-radius:6px;background:transparent;color:inherit}
@media(pointer:coarse){.reward-strip .reward-claim,.reward-strip .reward-rules-toggle,.reward-strip .reward-history summary,.reward-campaign-picker select{min-height:48px}}
.reward-strip{padding:18px 22px 14px;min-width:0}.reward-strip-head,.reward-strip-heading,.reward-strip-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.reward-strip-head{justify-content:space-between;gap:12px 24px}.reward-strip h2{font-size:14px;font-weight:650;color:inherit}.reward-strip-spent{font-size:12px;color:#718096;border-left:1px solid #e3e8ef;padding-left:12px;font-variant-numeric:tabular-nums}.reward-strip-actions p{font-size:12px;color:#637083}.reward-rules-toggle{font-size:12px;font-weight:600;color:inherit;min-height:32px;cursor:pointer}.reward-path-scroll{overflow-x:auto;scrollbar-width:thin;padding:15px 4px 4px}.reward-path{position:relative;min-width:calc(var(--tier-count)*130px);padding:0 30px}.reward-path-line{position:absolute;top:15px;left:calc(30px + (100% - 60px)/var(--tier-count)/2);right:calc(30px + (100% - 60px)/var(--tier-count)/2);height:5px;border-radius:6px;background:#edf0f4}.reward-path-line>span{display:block;height:100%;border-radius:6px;background:#24b88a;transition:width .35s ease}.reward-path-line>i{position:absolute;top:-4px;width:13px;height:13px;border:3px solid white;background:#159a74;border-radius:50%;transform:translateX(-50%)}.reward-milestones{display:grid;grid-template-columns:repeat(var(--tier-count),minmax(0,1fr));list-style:none;padding:0;margin:0}.reward-milestone{display:flex;align-items:center;flex-direction:column;gap:8px;position:relative;min-height:73px}.reward-node{display:flex;align-items:center;justify-content:center;width:30px;height:30px;border:1px solid #e0e6ed;background:white;border-radius:50%;color:#a9b3c1;box-shadow:0 0 0 4px white;z-index:1}.is-reached .reward-node{background:#159a74;border-color:#159a74;color:white;box-shadow:0 0 0 4px #e1f7ed}.reward-tier-label{display:flex;align-items:baseline;gap:5px;padding:3px 9px;border-radius:20px;background:#f3f5f8;color:#728095;font-size:10px;white-space:nowrap;font-variant-numeric:tabular-nums}.reward-tier-label b,.reward-tier-label strong{font-weight:600}.is-reached .reward-tier-label{background:#eaf9f1;color:#08795c}.reward-tier-state{font-size:10px;color:#7b8797}.reward-claim{min-height:32px;padding:5px 11px;border:1px solid #159a74;border-radius:6px;font-size:11px;font-weight:550;color:#08795c;background:#ecfaf3;cursor:pointer}.reward-claim:disabled{opacity:.5;cursor:wait}.reward-claim-all,.reward-wallet-bar{display:flex;gap:16px;align-items:center;justify-content:flex-end;font-size:12px;color:#138467;margin-top:8px}.reward-wallet-bar{justify-content:space-between;padding:8px 12px;border-radius:8px;background:#f0fdf4;border:1px solid #bbf7d0}.reward-notice{font-size:12px;color:#059669;margin-top:8px}.reward-strip-notice{font-size:11px;line-height:1.7;color:#967028;margin-top:8px}.reward-rules{padding:14px 16px;border:1px solid #dceae3;border-radius:8px;background:#f6fbf8;margin-top:12px;font-size:12px;line-height:1.9;color:#63756c}.reward-rules h3{font-weight:600;color:#1e5740;margin-bottom:5px}.reward-history{font-size:11px;margin-top:10px;border-top:1px solid #eef1f4;padding-top:10px}.reward-history summary{cursor:pointer;min-height:24px}.reward-error{color:#c13e3e;font-size:12px;margin-top:12px}.reward-error button{text-decoration:underline;min-height:32px}.reward-strip :is(button,summary):focus-visible{outline:2px solid #138467;outline-offset:3px}
@media(max-width:640px){.reward-strip{padding:16px}.reward-strip-actions{gap:8px;justify-content:space-between;width:100%}.reward-strip-actions p{font-size:11px}.reward-path{padding:0 8px}.reward-path-line{left:calc(8px + (100% - 16px)/var(--tier-count)/2);right:calc(8px + (100% - 16px)/var(--tier-count)/2)}.reward-strip button{min-height:44px}.reward-history summary{min-height:44px;display:flex;align-items:center}}
@media(prefers-reduced-motion:reduce){.reward-path-line>span{transition:none}}
</style>
<style>
.dark .reward-strip .reward-wallet-help{color:#a5b2c4}
.dark .reward-strip.reward-strip{background:#17212f;border-color:#344153;color:#e5edf6}.dark .reward-strip .reward-path-line{background:#344153}.dark .reward-strip .reward-path-line>i{border-color:#17212f}.dark .reward-strip .reward-node{background:#192638;border-color:#465568;box-shadow:0 0 0 4px #192638}.dark .reward-strip .is-reached .reward-node{background:#168d6c;border-color:#168d6c;box-shadow:0 0 0 4px #173d34}.dark .reward-strip .reward-tier-label{background:#293548;color:#a6b2c5}.dark .reward-strip .is-reached .reward-tier-label,.dark .reward-strip .reward-claim{background:#173d34;color:#8bdfbe}.dark .reward-strip .reward-wallet-bar{background:#123529;border-color:#166534;color:#8bdfbe}.dark .reward-strip .reward-rules{background:#172e27;border-color:#2c4a3e;color:#a5bdb0}.dark .reward-strip .reward-rules h3{color:#a6dfbf}.dark .reward-strip .reward-strip-spent,.dark .reward-strip .reward-strip-actions p{color:#a5b2c4}.dark .reward-strip .reward-history{border-color:#344153}.dark .reward-strip .reward-strip-notice{color:#d9b46a}
</style>
